SELECT COUNT(*) FROM (
    WITH pru_per_record AS (
        SELECT p.equipref
        FROM processing p
        JOIN mesh m ON p.zoneref = m.zoneref AND p.equipref = m.equipref
    ),
    equipment_agg AS (
        SELECT equipref FROM pru_per_record GROUP BY equipref
    )
    SELECT * FROM equipment_agg
) sub;

-- Equipment in processing but NOT in equipment table
SELECT COUNT(*) FROM (
    SELECT DISTINCT p.equipref FROM processing p
    EXCEPT
    SELECT equipregistry FROM equipment
) sub;

-- Equipment in equipment table but NOT in processing
SELECT COUNT(*) FROM (
    SELECT equipregistry FROM equipment
    EXCEPT
    SELECT DISTINCT equipref FROM processing
) sub;

-- Maybe it's equipment LEFT JOIN processing (not aggregated), giving one row per processing record per equipment
SELECT COUNT(*) FROM equipment e 
LEFT JOIN processing p ON e.equipregistry = p.equipref;

-- Check if there's another table that could contribute rows
SELECT COUNT(*) FROM (
    SELECT e.equipregistry FROM equipment e
    UNION ALL
    SELECT DISTINCT p.equipref FROM processing p
) sub;

-- Maybe join on zoneref instead of equipref?
SELECT COUNT(*) FROM equipment e 
JOIN processing p ON e.equipregistry = p.equipref;
